function pick(setName,match){
  const direct = all.find(n=>n.name===setName);
  if(direct && direct.type==='COMPONENT_SET'){
    const c=direct.children.find(x=>x.name.indexOf(match)>=0);
    if(c) return c;
  }
  const bySlash = all.find(n=>n.type==='COMPONENT' && n.name===setName+' / '+match);
  if(bySlash) return bySlash;
  const loose = all.find(n=>n.type==='COMPONENT' && n.name.indexOf(setName)===0 && n.name.indexOf(match)>=0);
  if(loose) return loose;
  if(direct && direct.type==='COMPONENT') return direct;
  log.push('MISS '+setName+' | '+match);
  return null;
}
