  i.findAll(n=>n.type==='VECTOR').forEach(v=>{ if(v.strokes&&v.strokes.length) v.strokes=[{type:'SOLID',color:H(color)}]; }); return i; }
function grad(w,h,from,to){ const r=figma.createRectangle(); r.name='Scrim'; r.resize(w,h);
  r.fills=[{type:'GRADIENT_LINEAR',gradientTransform:[[1,0,0],[0,1,0]],gradientStops:[
    {position:0,color:{r:from.r,g:from.g,b:from.b,a:from.a}},{position:1,color:{r:to.r,g:to.g,b:to.b,a:to.a}}]}]; return r; }
