function setText(inst,nm,val){ const n=inst.findOne(x=>x.type==='TEXT'&&x.name===nm); if(n) n.characters=val; return n; }

const all=page.findAll(n=>n.type==='COMPONENT'||n.type==='COMPONENT_SET');
function pick(setName,match){
  const direct = all.find(n=>n.name===setName);
  if(direct && direct.type==='COMPONENT_SET'){ const c=direct.children.find(x=>x.name.indexOf(match)>=0); if(c) return c; }
  const bySlash = all.find(n=>n.type==='COMPONENT' && n.name===setName+' / '+match);
  if(bySlash) return bySlash;
  const loose = all.find(n=>n.type==='COMPONENT' && n.name.indexOf(setName)===0 && n.name.indexOf(match)>=0);
  if(loose) return loose;
  if(direct && direct.type==='COMPONENT') return direct;
  return null;
}
function inst(setName,match){ const c=pick(setName,match); if(!c) throw new Error('unresolved: '+setName+' | '+match); return c.createInstance(); }

