function txt(str,style,color,opt){ const t=figma.createText(); t.fontName=F.R; const st=S(style); if(st) t.textStyleId=st.id;
  t.characters=str; if(opt&&opt.size) t.fontSize=opt.size; if(opt&&opt.bold) t.fontName=F.B; if(opt&&opt.black) t.fontName=F.K;
  if(opt&&opt.w){ t.textAutoResize='HEIGHT'; t.resize(opt.w,t.height); }
  try{ t.textDecoration='NONE'; }catch(e){}
  t.fills=[{type:'SOLID',color:H(color)}]; return t; }
function rect(name,w,h,fill,rad){ const r=figma.createRectangle(); r.name=name; r.resize(w,h); r.cornerRadius=rad||0;
  r.fills=fill?[{type:'SOLID',color:H(fill)}]:[]; return r; }
function photo(hash,w,h,rad){ const r=figma.createRectangle(); r.name='Photo'; r.resize(w,h); if(rad) r.cornerRadius=rad;
  r.fills=[{type:'IMAGE',scaleMode:'FILL',imageHash:hash}]; return r; }
function icon(id,color,size){ const i=figma.getNodeById(id).createInstance(); i.resize(size,size);
  i.findAll(n=>n.type==='VECTOR').forEach(v=>{ if(v.strokes&&v.strokes.length) v.strokes=[{type:'SOLID',color:H(color)}]; }); return i; }
function grad(w,h,from,to){ const r=figma.createRectangle(); r.name='Scrim'; r.resize(w,h);
  r.fills=[{type:'GRADIENT_LINEAR',gradientTransform:[[1,0,0],[0,1,0]],gradientStops:[
    {position:0,color:{r:from.r,g:from.g,b:from.b,a:from.a}},{position:1,color:{r:to.r,g:to.g,b:to.b,a:to.a}}]}]; return r; }
const dk=a=>({r:0.098,g:0.129,b:0.149,a:a});
const SH=(a,y)=>[{type:'DROP_SHADOW',color:{r:0.098,g:0.129,b:0.149,a:a},offset:{x:0,y:y===undefined?8:y},radius:20,spread:0,visible:true,blendMode:'NORMAL'}];
function setText(node,nm,val){ const n=node.findOne(x=>x.type==='TEXT'&&x.name===nm); if(n) n.characters=val; return n; }
function mkComp(name,w,h,fill,rad){ const c=figma.createComponent(); c.name=name; c.resize(w,h); c.cornerRadius=rad||0;
  c.fills=fill?[{type:'SOLID',color:H(fill)}]:[]; c.clipsContent=false; return c; }

