function act(sel,label,dest,root){ const t=root&&root.findOne(sel); if(t){ nav(t,dest); done.push(label); } else miss.push(label); }
const f1=figma.getNodeById(KEEP['01_Onboarding']);
const f2=figma.getNodeById(KEEP['02_Home']);
const f3=figma.getNodeById(KEEP['03_Explore']);
const f4=figma.getNodeById(KEEP['04_Workout']);
const f5=figma.getNodeById(KEEP['05_Analytics']);
const tabLabel=(root,lbl)=>root&&root.findAll(n=>n.type==='INSTANCE'&&n.name.indexOf('TabItem / '+lbl)>=0)[0];
act(n=>n.name==='CTA / Get Started','01 CTA',KEEP['02_Home'],f1);
act(n=>n.name==='Card / Lower Body Training','02 card',KEEP['04_Workout'],f2);
[{l:'Explore',d:'03_Explore'},{l:'Analytics',d:'05_Analytics'}].forEach(p=>{
  const t=tabLabel(f2,p.l); if(t){ nav(t,KEEP[p.d]); done.push('02→'+p.l); } else miss.push('02 '+p.l);
});
[{l:'Home',d:'01_Onboarding'},{l:'Analytics',d:'05_Analytics'}].forEach(p=>{
  const t=tabLabel(f3,p.l); if(t){ nav(t,KEEP[p.d]); done.push('03→'+p.l); } else miss.push('03 '+p.l);
});
act(n=>n.name==='Back','04 back',KEEP['02_Home'],f4);
[{l:'Home',d:'01_Onboarding'},{l:'Explore',d:'03_Explore'}].forEach(p=>{
  const t=tabLabel(f5,p.l); if(t){ nav(t,KEEP[p.d]); done.push('05→'+p.l); } else miss.push('05 '+p.l);
});
try{ page.flowStartingPoints=[{nodeId:KEEP['01_Onboarding'],name:'Fitness App · Flow'}]; }catch(e){ miss.push('flow '+e.message); }
return JSON.stringify({removed,done,miss,pageChildren:page.children.map(c=>c.name+':'+c.id)});

const page=figma.getNodeById('7:2');
const frames=page.children.filter(c=>c.type==='FRAME'&&/^\d\d_/.test(c.name)).map(c=>({id:c.id,name:c.name,w:Math.round(c.width),h:Math.round(c.height)}));
const links=[]; page.findAll(n=>n.reactions&&n.reactions.length).forEach(n=>{
  const r=n.reactions[0]; const a=(r.actions&&r.actions[0])||{};
  links.push({from:n.name,dest:a.destinationId,alive:!!(a.destinationId&&figma.getNodeById(a.destinationId))});
});
const ts=await figma.getLocalTextStylesAsync(); const ps=await figma.getLocalPaintStylesAsync();
const lib1=page.children.find(c=>c.name==='03 Components · Fitness');
const lib2=page.children.find(c=>c.name==='05 Components · Screens');
const tab=page.children.find(c=>c.name==='02_Home').findOne(n=>n.type==='INSTANCE'&&n.name.indexOf('TabBar')>=0);
return JSON.stringify({frames,links,flows:(page.flowStartingPoints||[]).map(f=>f.nodeId+' '+f.name),
 textStyles:ts.length,paintStyles:ps.map(p=>p.name),lib1Kids:lib1&&lib1.children.length,lib2Kids:lib2&&lib2.children.length,
 tabHome:tab&&tab.name, pageChildCount:page.children.length});
